def solve_n(n):
    M = n * (n - 1) // 2

    # b_1, b_2, ..., b_n such that {b_i + b_j} = {1, ..., M}
    # b_1 = 0, b_2 = 1

    def backtrack(current_b, sums_so_far):
        if len(current_b) == n:
            if len(sums_so_far) == M and max(sums_so_far) == M and min(sums_so_far) == 1:
                return current_b
            return None

        last_b = current_b[-1]
        # b_n < M
        for next_b in range(last_b + 1, M + 1):
            new_sums = []
            possible = True
            for i in range(len(current_b)):
                s = current_b[i] + next_b
                if s > M or s in sums_so_far:
                    possible = False
                    break
                new_sums.append(s)

            if possible:
                # Add b_1 + b_n (which is next_b since b_1=0)
                # Wait, sums_so_far already contains b_i + b_j for i < j < n.
                # The only new sums are b_i + b_n for i = 1...n-1.
                # Let's re-think this.

                # New sums are {b_1+b_n, b_2+b_n, ..., b_{n-1}+b_n}
                # b_1 is always 0.
                # So the sums are {next_b, b_2+next_b, ..., b_{n-1}+next_b}

                # Wait, the current_b is [b_1, b_2, ..., b_k].
                # The sums_so_far are {b_i+b_j : 1 <= i < j <= k}.
                # When we add b_{k+1}, the new sums are {b_i+b_{k+1} : 1 <= i <= k}.

                # Let's trace:
                # current_b = [0, 1]
                # sums_so_far = {1}
                # next_b = 2
                # new_sums = {0+2, 1+2} = {2, 3}
                # sums_so_far = {1, 2, 3}

                # Yes, this is correct.
                # Let's re-write the backtrack to be clearer.
                pass

    # Let's just use a simpler backtracking.
    def backtrack_simple(current_b, sums_so_far):
        if len(current_b) == n:
            return current_b

        last_b = current_b[-1]
        for next_b in range(last_b + 1, M + 1):
            new_sums = []
            possible = True
            for i in range(len(current_b)):
                s = current_b[i] + next_b
                if s > M or s in sums_so_far:
                    possible = False
                    break
                new_sums.append(s)

            if possible:
                for s in new_sums:
                    sums_so_far.add(s)

                res = backtrack_simple(current_b + [next_b], sums_so_far)
                if res: return res

                for s in new_sums:
                    sums_so_far.remove(s)
        return None

    # Initial state: b_1=0, b_2=1
    # sums_so_far = {b_1+b_2} = {1}
    res = backtrack_simple([0, 1], {1})
    return res

for n in range(3, 10):
    print(f"n={n}: {solve_n(n)}")
